from taf.gnb.oam.coam.admin.interfaces.admin_20a import ADMIN20A
from taf.gnb.oam.coam.admin.schemas.procedure.ccm_uplink_pucch_admin20b import CCMUplinkPucch


class ADMIN20B(ADMIN20A):
    def __init__(self,
                 api_client=None
                 ):
        """
        :param api_client: instance of an AdminApi class
        """
        super(ADMIN20B, self).__init__(api_client)

    def perform_ncf_commissioning(self, ncf_filepath, timeout=120):
        """
        Perform NCF commissioning.

        :param str ncf_filepath: Filepath to NCF file.
        :param int timeout: (optional) Timeout for the operation, defaults to 120
        :return: str: status "Completed" or "Failed"
        """
        return self._api_client.execute_procedure('activeNCF',
                                                  parameters={},
                                                  timeout=timeout,
                                                  input_file_name=ncf_filepath)

    def start_5g_uplink_ccm_test_pucch(self, dist_name, nrarfcn_ul, interval,
                                       beam_pattern_id, receiving_slot,
                                       expectation_slot, pucch_format, ru_mode,
                                       phys_cell_id, format3_additional_dmrs,
                                       prb_offset, largest_prb_index, num_pucch_symbol,
                                       num_payload_bit, pucch_payload_content,
                                       timeout=60, **kwargs):
        """
        Starts 5G `Pucch` Performance CCM Test (start5GUplinkCCMTest).

        :param str dist_name: `NRCELL_R` object to perform the test on.
        :param int nrarfcn_ul: (Optional) [0..3279165].
        :param int interval: Reporting time interval [1..3600].
        :param int beam_pattern_id: [0..1200].
        :param str ru_mode: One of the following:
                            `NR_Only`, `MSR` (`MSR` is supported when RU contains EUTRA.Frequency.Band)
        :param int phys_cell_id: [0..1007].

        pucchParams:
        :param int receiving_slot: [0..1023].
        :param int expectation_slot: [0..1023].
        :param str pucch_format: Either `F0` or `F2`. (from version admin20b also values: `F1` and `F3`).
        :param str format3_additional_dmrs: `Disabled` (required in admin20b)
        :param int prb_offset: [0..272] (required in admin20b)
        :param int largest_prb_index: [0..272] (required in admin20b)
        :param int num_pucch_symbol: [0..255] (required in admin20b)
        :param int num_payload_bit: [0..255] (required in admin20b)
        :param int pucch_payload_content: [0..4294967295] (required in admin20b)
        :param int timeout: (optional) Timeout for the operation.
        :return: It returns dict with data.

        Example response

        ::

            {
              "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0",
              "confirmationNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/ACK-1",
                 "parameters": {}
              },
              "resultNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/NR_TEST_RESULT-1",
                 "parameters": {
                    "status": "Succeeded"
                 }
              }
           }

        More details:
        https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-start5GUplinkCCMTest.html

        """
        interval = int(interval)
        beam_pattern_id = int(beam_pattern_id)
        prb_offset = int(prb_offset)
        largest_prb_index = int(largest_prb_index)
        num_pucch_symbol = int(num_pucch_symbol)
        num_payload_bit = int(num_payload_bit)
        pucch_payload_content = int(pucch_payload_content)

        PERFORMANCE_TEST_TYPE = "Pucch"

        pucch_schema = CCMUplinkPucch(nrcell_rdn=dist_name, nrarfcn_ul=nrarfcn_ul, reporting_time_interval=interval,
                                      beam_pattern_id=beam_pattern_id, ru_mode=ru_mode, phys_cell_id=phys_cell_id,
                                      performance_test_type=PERFORMANCE_TEST_TYPE,
                                      receiving_slot=receiving_slot, expectation_slot=expectation_slot,
                                      pucch_format=pucch_format, format3_additional_dmrs=format3_additional_dmrs,
                                      prb_offset=prb_offset, largest_prb_index=largest_prb_index,
                                      num_pucch_symbol=num_pucch_symbol, num_payload_bit=num_payload_bit,
                                      pucch_payload_content=pucch_payload_content
                                      )

        parameters = pucch_schema.as_dict()

        return self._api_client.execute_procedure('start5GUplinkCCMTest',
                                                  parameters, timeout)
